class Solution
{
public:
    bool canPermutePalindrome(string s)
    {
        unordered_set< char>odd;
        for (char c : s)
        {
            if (odd.count(c))
            {
                odd.erase(c);
            }
            else odd.insert(c);
        }
        return odd.size() <= 1;
    }
};
